// src/entities/VCEntity.ts
class VCEntity extends OutreachEntity {
  typeData;
  constructor(data = {}) {
    super({ ...data, type: "vc" });
    this.typeData = {
      firmType: data.typeData?.firmType || data.firmType || "vc",
      stageFocus: data.typeData?.stageFocus || data.stageFocus || [],
      sectorFocus: data.typeData?.sectorFocus || data.sectorFocus || [],
      checkSizeMin: data.typeData?.checkSizeMin ?? data.checkSizeMin ?? null,
      checkSizeMax: data.typeData?.checkSizeMax ?? data.checkSizeMax ?? null,
      aum: data.typeData?.aum ?? data.aum ?? null,
      partners: data.typeData?.partners || data.partners || [],
      portfolioCompanies: data.typeData?.portfolioCompanies || data.portfolioCompanies || [],
      recentInvestments: data.typeData?.recentInvestments || data.recentInvestments || [],
      linkedInUrl: data.typeData?.linkedInUrl ?? data.linkedInUrl ?? null,
      crunchbaseUrl: data.typeData?.crunchbaseUrl ?? data.crunchbaseUrl ?? null,
      relevanceScore: data.typeData?.relevanceScore ?? data.relevanceScore ?? null,
      contactFormUrl: data.typeData?.contactFormUrl ?? data.contactFormUrl ?? null,
      outreachMethod: data.typeData?.outreachMethod ?? data.outreachMethod ?? undefined,
      outreachMethodReason: data.typeData?.outreachMethodReason ?? data.outreachMethodReason ?? undefined
    };
  }
  getPrimaryPartner() {
    if (!this.typeData.partners || this.typeData.partners.length === 0) {
      return null;
    }
    const governanceKeywords = ["AI", "safety", "governance", "alignment", "ethics", "policy"];
    const governancePartner = this.typeData.partners.find((p) => governanceKeywords.some((kw) => (p.focus || p.title || "").toLowerCase().includes(kw.toLowerCase())));
    return governancePartner || this.typeData.partners[0];
  }
  getLinkedInUrl() {
    const partner = this.getPrimaryPartner();
    if (partner?.linkedInUrl)
      return partner.linkedInUrl;
    return this.typeData.linkedInUrl || null;
  }
  getContactFormUrl() {
    if (this.typeData.contactFormUrl)
      return this.typeData.contactFormUrl;
    if (this.website)
      return `${this.website}/contact`;
    return null;
  }
  hasGenericEmail() {
    if (!this.email)
      return false;
    const lower = this.email.toLowerCase();
    const genericPrefixes = ["info@", "contact@", "hello@", "inquiries@", "general@", "admin@", "support@", "team@", "press@"];
    return genericPrefixes.some((prefix) => lower.startsWith(prefix));
  }
  matchesCriteria(criteria) {
    if (criteria.stages && criteria.stages.length > 0) {
      const hasMatchingStage = (this.typeData.stageFocus || []).some((stage) => criteria.stages.includes(stage.toLowerCase()));
      if (!hasMatchingStage)
        return false;
    }
    if (criteria.sectors && criteria.sectors.length > 0) {
      const hasMatchingSector = (this.typeData.sectorFocus || []).some((sector) => criteria.sectors.some((cs) => sector.toLowerCase().includes(cs.toLowerCase())));
      if (!hasMatchingSector)
        return false;
    }
    if (criteria.checkSizeMin && this.typeData.checkSizeMax) {
      if (this.typeData.checkSizeMax < criteria.checkSizeMin)
        return false;
    }
    if (criteria.checkSizeMax && this.typeData.checkSizeMin) {
      if (this.typeData.checkSizeMin > criteria.checkSizeMax)
        return false;
    }
    return true;
  }
  toJSON() {
    return {
      ...super.toJSON(),
      typeData: this.typeData
    };
  }
  static fromJSON(data) {
    return new VCEntity(data);
  }
}

// src/strategies/StrategyRegistry.ts
class StrategyRegistry {
  strategies;
  constructor() {
    this.strategies = new Map;
  }
  register(type, action, strategy) {
    if (!this.strategies.has(type)) {
      this.strategies.set(type, new Map);
    }
    this.strategies.get(type).set(action, strategy);
  }
  registerDefault(action, strategy) {
    this.register("default", action, strategy);
  }
  get(type, action) {
    if (this.strategies.has(type)) {
      const typeStrategies = this.strategies.get(type);
      if (typeStrategies.has(action)) {
        return typeStrategies.get(action);
      }
    }
    return this.getDefault(action);
  }
  getDefault(action) {
    if (this.strategies.has("default")) {
      const defaultStrategies = this.strategies.get("default");
      if (defaultStrategies.has(action)) {
        return defaultStrategies.get(action);
      }
    }
    return null;
  }
  has(type, action) {
    return this.get(type, action) !== null;
  }
  getTypes() {
    return Array.from(this.strategies.keys()).filter((t) => t !== "default");
  }
  getActions(type) {
    if (this.strategies.has(type)) {
      return Array.from(this.strategies.get(type).keys());
    }
    return [];
  }
}

