// src/strategies/research/MunicipalResearchStrategy.ts
class MunicipalResearchStrategy extends ResearchStrategy {
  constructor(config = {}) {
    super(config);
    this.name = "municipal-research";
  }
  async research(entity) {
    console.log(`\uD83D\uDCDA Researching municipality: ${entity.name}...`);
    if (entity.location.country === "Costa Rica") {
      return this.researchCostaRica(entity);
    }
    return this.researchGeneric(entity);
  }
  researchCostaRica(entity) {
    const cantonName = entity.name.replace("Municipalidad de ", "");
    const canton = COSTA_RICA_CANTONES.find((c) => c.name === cantonName);
    if (!canton) {
      return this.researchGeneric(entity);
    }
    const research = {
      population: canton.population,
      budget: canton.budget,
      province: canton.province,
      initiatives: [
        { name: "Transformaci\xF3n Digital Municipal", description: "Modernizaci\xF3n de servicios ciudadanos", status: "active", budget: canton.budget * 0.05 },
        { name: "Gobierno Abierto", description: "Transparencia y datos abiertos", status: "active", budget: canton.budget * 0.02 }
      ],
      painPoints: [
        "Complejidad de la transformaci\xF3n digital",
        "Recursos t\xE9cnicos limitados",
        "Entrega de servicios ciudadanos",
        "Gobernanza de datos y privacidad",
        "Coordinaci\xF3n interinstitucional"
      ],
      trAigaRelevant: true,
      keyContacts: this.generateKeyContacts(canton.name)
    };
    entity.researchNotes = `Cant\xF3n de la provincia de ${canton.province}. Poblaci\xF3n: ${canton.population}. Iniciativas clave: ${research.initiatives.map((i) => i.name).join(", ")}.`;
    entity.personalizationContext = {
      painPoints: research.painPoints,
      tailoredHook: "Apoyo en implementaci\xF3n del TRAIGA Act",
      valueProposition: "Apoyo en gobernanza de IA y transformaci\xF3n digital municipal"
    };
    if (!entity.typeData.population) {
      entity.typeData.population = canton.population;
    }
    if (!entity.typeData.budget) {
      entity.typeData.budget = canton.budget;
    }
    if (!entity.typeData.province) {
      entity.typeData.province = canton.province;
    }
    entity.typeData.initiatives = research.initiatives;
    entity.typeData.painPoints = research.painPoints;
    entity.typeData.keyContacts = research.keyContacts;
    entity.typeData.trAigaRelevant = true;
    if (!entity.typeData.population || !entity.typeData.province) {
      throw new Error(`Research incomplete for ${entity.name}: population=${entity.typeData.population}, province=${entity.typeData.province}`);
    }
    entity.updateStatus("researched");
    console.log(`   \u2705 Research complete for ${canton.name}`);
    return {
      success: true,
      research,
      entity
    };
  }
  researchGeneric(entity) {
    const research = {
      initiatives: [
        { name: "Transformaci\xF3n Digital", description: "Modernizaci\xF3n de servicios municipales", status: "active" },
        { name: "Participaci\xF3n Ciudadana", description: "Mejora de la participaci\xF3n p\xFAblica", status: "planned" }
      ],
      painPoints: [...SPANISH_PAIN_POINTS],
      keyContacts: this.generateKeyContacts(entity.name)
    };
    entity.researchNotes = `Investigaci\xF3n municipal: Enfoque en transformaci\xF3n digital y servicios ciudadanos.`;
    entity.personalizationContext = {
      painPoints: research.painPoints,
      tailoredHook: "Apoyo en gobernanza municipal"
    };
    entity.typeData.initiatives = research.initiatives;
    entity.typeData.painPoints = research.painPoints;
    entity.typeData.keyContacts = research.keyContacts;
    entity.updateStatus("researched");
    return {
      success: true,
      research,
      entity
    };
  }
  async researchDryRun(entity) {
    console.log(`\uD83D\uDCDA [DRY RUN] Researching municipality: ${entity.name}...`);
    const mockResearch = {
      initiatives: [
        { name: "Transformaci\xF3n Digital", description: "Modernizaci\xF3n de servicios", status: "active", budget: 1e5 }
      ],
      painPoints: [...SPANISH_PAIN_POINTS],
      trAigaRelevant: true,
      keyContacts: []
    };
    entity.researchNotes = "Research notes would be generated here.";
    entity.personalizationContext = {
      painPoints: mockResearch.painPoints,
      tailoredHook: "Apoyo en implementaci\xF3n del TRAIGA Act"
    };
    entity.updateStatus("researched");
    console.log(`   [DRY RUN] Research complete`);
    return {
      success: true,
      research: mockResearch,
      entity
    };
  }
  generateKeyContacts(municipalityName) {
    return [];
  }
}

