class ValidationStrategy {
  config;
  validatorType;
  constructor(config = {}) {
    this.config = config;
    this.validatorType = config.validatorType || "regex-mx";
  }
  initialize() {}
  async validate(entity) {
    if (!entity.email) {
      return {
        result: "unknown",
        confidence: 0,
        details: { reason: "no_email" },
        validator: "none"
      };
    }
    console.log(`\uD83D\uDD0D Validating email: ${entity.email}`);
    try {
      const { EmailValidatorFactory: EmailValidatorFactory2 } = await Promise.resolve().then(() => (init_EmailValidatorFactory(), exports_EmailValidatorFactory));
      const validatorConfig = this.validatorType === "zerobounce" ? { apiKey: process.env.ZEROBOUNCE_API_KEY } : {};
      const validator = EmailValidatorFactory2.create(this.validatorType, validatorConfig);
      const result = await validator.validate(entity.email);
      entity.setEmailValidation(result);
      if (result.result === "valid") {
        console.log(`   \u2705 Email validated (${result.confidence * 100}% confidence)`);
        entity.updateStatus("validated");
      } else {
        console.log(`   \u26A0\uFE0F  Email ${result.result}: ${result.details?.reason || "unknown"}`);
      }
      return result;
    } catch (error) {
      const err = error;
      console.error(`   \u274C Validation failed: ${err.message}`);
      return {
        result: "error",
        confidence: 0,
        details: { error: err.message },
        validator: this.validatorType
      };
    }
  }
  async validateBatch(entities, options = {}) {
    const results = [];
    for (const entity of entities) {
      const result = await this.validate(entity);
      results.push({ entity: entity.name, result });
      if (options.rateLimitMs && options.rateLimitMs > 0) {
        await new Promise((resolve) => setTimeout(resolve, options.rateLimitMs));
      }
    }
    return results;
  }
}

