// src/core/tracing-utils.ts
async function traceOperation(name, operation, attributes = {}) {
  const tracer = getTracer();
  return tracer.startActiveSpan(name, async (span) => {
    for (const [key, value] of Object.entries(attributes)) {
      span.setAttribute(key, value);
    }
    try {
      const result = await operation(span);
      span.setStatus({ code: import_api2.SpanStatusCode.OK });
      return result;
    } catch (error) {
      if (error instanceof Error) {
        span.recordException(error);
        span.setStatus({ code: import_api2.SpanStatusCode.ERROR, message: error.message });
      } else {
        span.recordException(new Error(String(error)));
        span.setStatus({ code: import_api2.SpanStatusCode.ERROR, message: String(error) });
      }
      throw error;
    } finally {
      span.end();
    }
  });
}

